#include "melodee/shell/drum_tool.h"
#include "melodee/shell/context.h"
#include "melodee/shell/harmony_preview.h"
#include "melodee/shell/roll.h"
#include "melodee/engine/engine_host.h"
#include "melodee/shell/sample_library.h"
#include <cctype>
namespace melodee {
namespace {
uint64_t fingerprint(const Pattern& p){uint64_t h=1469598103934665603ull;auto mix=[&](uint64_t v){h=(h^v)*1099511628211ull;};mix(p.length);mix(p.events.size());for(auto e:p.events){mix(e.tick);mix(e.length);mix(e.key);mix(e.velocity);mix(e.pitch);mix(e.flags);mix(e.ratchet);mix(e.chance);mix(e.ramp);mix(e.pitch_ramp);mix(e.condition);mix(e.cutoff);}return h;}
bool valid(Context& c){auto& d=c.ui.drums;return d.owner==c.ui.track&&c.track().engine==EngineKind::Sampler&&!c.track().levels&&c.track().pattern==d.pattern&&!c.frozen(d.owner)&&!c.ui.recording&&!c.ui.rendering&&c.project.bar_ticks()==384&&c.project.beat_ticks()==96;}
void auto_map(Context& c){auto& d=c.ui.drums;d.pads.fill(0);for(unsigned pad=0;pad<128;++pad){const auto& sound=c.track().pads[pad];if(!sound.used())continue;std::string name=c.project.samples[sound.sample].name;for(char& ch:name)ch=char(std::tolower(static_cast<unsigned char>(ch)));int role=-1;
 if(name.find("kick")!=name.npos||name.find("bass drum")!=name.npos)role=0;else if(name.find("snare")!=name.npos||name.find("snr")!=name.npos||name.find("rim")!=name.npos)role=1;
 else if(name.find("open")!=name.npos&&(name.find("hat")!=name.npos||name.find("hh")!=name.npos))role=3;
 else if(name.find("hat")!=name.npos||name.find("hh")!=name.npos)role=2;else if(name.find("clap")!=name.npos)role=4;
 else if(name.find("tom")!=name.npos)role=6;else if(name.find("cym")!=name.npos||name.find("crash")!=name.npos||name.find("ride")!=name.npos)role=7;
 else if(name.find("perc")!=name.npos||name.find("shak")!=name.npos||name.find("conga")!=name.npos||name.find("tamb")!=name.npos)role=5;
 if(role>=0&&!d.pads[unsigned(role)])d.pads[unsigned(role)]=uint8_t(pad+1);
 }}
bool mapped(Context& c,std::vector<Event>& events){auto& d=c.ui.drums;std::string error;auto pads=drum_active_pads(d);for(unsigned pad:pads)if(pad&&!c.track().pads[pad-1].used()){c.notice("Mapped pad is empty; choose a loaded drum");return false;}if(!drums::notes(d.hits,pads,d.settings.bars*384,events,error)){c.notice(error);return false;}return true;}
bool generate(Context& c,bool again){auto& d=c.ui.drums;drum_stop(c);if(!valid(c)){c.notice("Choose a drum Roll in 4/4; stop recording");return false;}auto settings=d.settings;if(again)++settings.seed;std::vector<drums::Hit> hits;std::string error;if(!drums::generate(settings,d.hits,hits,error)){c.notice(error);return false;}d.settings=settings;d.hits=std::move(hits);d.stale=false;c.notice("Beat generated; preview or add to Roll");return true;}
void listen(Context& c){auto& d=c.ui.drums;if(d.rhythm_preview_count){drum_stop(c);return;}if(!valid(c)||c.host.playing()){c.notice("Stop playback before beat preview");return;}if(d.stale||d.hits.empty()){c.notice("Generate a beat first");return;}std::vector<Event> events;if(!mapped(c,events))return;unsigned count=0;for(auto e:events)if(e.tick/768==d.preview_pair)++count;if(count>d.rhythm_preview.size()){c.notice("Beat preview too dense");return;}d.rhythm_preview_next=0;d.rhythm_preview_active.fill(false);d.rhythm_preview_count=0;for(auto e:events)if(e.tick/768==d.preview_pair)d.rhythm_preview[d.rhythm_preview_count++]={e.tick-d.preview_pair*768u,e.length,e.key,e.velocity};d.rhythm_preview_start=c.now;d.rhythm_preview_tempo=c.project.tempo_of(d.pattern);c.notice("Preview selected bars / Push to stop");}
void apply(Context& c,bool keep){auto& d=c.ui.drums;drum_stop(c);if(!valid(c)||d.stale||fingerprint(c.pattern())!=d.fingerprint){d.confirm=false;c.notice("Roll changed; reopen Drum Generator");return;}std::vector<Event> events;if(!mapped(c,events))return;Pattern made;std::string error;if(!drums::edit(c.pattern(),events,d.settings.bars*384,keep,made,error)){c.notice(error);return;}
 c.edit_pattern(d.owner,d.pattern,keep?"Add generated beat":"Replace with generated beat",[&]{c.pattern()=std::move(made);c.sync_pattern(d.owner,d.pattern);});d.open=false;d.confirm=false;c.dirty=true;c.notice(keep?"Beat added; existing notes kept":"Roll replaced with generated beat");}
int limit(const DrumTool& d){if(d.page==1)return d.row==1?1:128;static const int limits[]={int(drums::genres)-1,4,100,75,100,999};return limits[d.row%6];}
int value(const DrumTool& d){if(d.page==1)return d.row==1?d.settings.locked[d.role]:d.pads[d.role];switch(d.row){case 0:return d.settings.genre;case 1:{unsigned n=0;for(unsigned b=1;b<d.settings.bars&&n<4;b*=2)++n;return int(n);}case 2:return d.settings.density;case 3:return d.settings.swing;case 4:return d.settings.fills;default:return int(d.settings.seed%1000);}}
void set(Context& c,int v){auto& d=c.ui.drums;d.field_changed_at=c.now;drum_stop(c);v=std::clamp(v,d.page==0&&d.row==3?50:0,limit(d));if(d.page==1){if(d.row==1)d.settings.locked[d.role]=v!=0;else d.pads[d.role]=uint8_t(v);return;}switch(d.row){case 0:d.settings.genre=v;break;case 1:d.settings.bars=uint8_t(1u<<v);d.preview_pair=std::min<uint8_t>(d.preview_pair,uint8_t((d.settings.bars-1)/2));break;case 2:d.settings.density=v;break;case 3:d.settings.swing=v;break;case 4:d.settings.fills=v;break;default:d.settings.seed=v;break;}d.stale=true;}
}
void drum_stop(Context& c){auto& d=c.ui.drums;stop_harmony_preview(d,[&](unsigned key){c.note(d.owner,key,0);});}
void drum_open(Context& c){if(c.track().engine!=EngineKind::Sampler||c.track().levels||c.project.bar_ticks()!=384||c.project.beat_ticks()!=96||c.ui.recording||c.ui.rendering||c.frozen(c.ui.track)){c.notice("Drum Generator: drum kit Roll, 4/4, stopped take");return;}drum_stop(c);c.stop_preview();auto& d=c.ui.drums;d=DrumTool{};d.open=true;d.field_changed_at=c.now;d.owner=c.ui.track;d.pattern=c.track().pattern;d.fingerprint=fingerprint(c.pattern());auto_map(c);c.ui.sheet_open=false;for(auto& p:c.ui.pots){p.bound=0;p.engaged=false;}}
void drum_tick(Context& c){auto& d=c.ui.drums;if(d.browsing){drum_stop(c);if(!valid(c)){d.browsing=false;d.open=false;return;}if(c.ui.page==PageId::Samples)return;d.browsing=false;c.track().last_pad=d.previous_pad;d.field_changed_at=c.now;}if(d.open&&(c.ui.page!=PageId::Roll||!valid(c))){drum_stop(c);d.open=false;d.confirm=false;return;}if(!d.rhythm_preview_count)return;if(!d.open||c.ui.page!=PageId::Roll||!valid(c)||c.host.playing()){drum_stop(c);return;}advance_harmony_preview(d,c.now-d.rhythm_preview_start,[&](unsigned key,unsigned v){c.note(d.owner,key,uint8_t(v));},[&](unsigned key){c.note(d.owner,key,0);});}
void drum_pot(Context& c,unsigned knob,int position){auto& d=c.ui.drums;d.field_changed_at=c.now;if(d.confirm)return;position=std::clamp(position,0,127);if(knob==2){drum_stop(c);d.role=uint8_t(position*drums::roles/128);}else if(knob==0){if(d.page==2){drum_stop(c);d.preview_pair=uint8_t(position*((d.settings.bars+1)/2)/128);}else if(d.page<2)d.row=uint8_t(position*(d.page==1?2:6)/128);}else if(d.page==2){bool muted=position>=64;if(muted!=d.muted[d.role]){drum_stop(c);d.muted[d.role]=muted;}}else if(d.page<2)set(c,position*limit(d)/127);}
void drum_wheel(Context& c,int delta){auto& d=c.ui.drums;if(d.confirm){d.confirm_pick=uint8_t(std::clamp(int(d.confirm_pick)+delta,0,2));return;}if(d.page==2){drum_stop(c);d.preview_pair=uint8_t(std::clamp(int(d.preview_pair)+delta,0,int((d.settings.bars-1)/2)));}else if(d.page<2)set(c,value(d)+delta);}
void drum_push(Context& c){auto& d=c.ui.drums;if(d.confirm){if(d.confirm_pick==0)d.confirm=false;else apply(c,d.confirm_pick==1);return;}if(d.page==2)listen(c);else if(d.page==3){if(d.stale||d.hits.empty()){c.notice("Generate a beat first");return;}d.confirm=true;d.confirm_pick=0;}else if(d.page==0)generate(c,!d.stale&&!d.hits.empty());else if(d.row==1)set(c,!d.settings.locked[d.role]);else drum_browse_sound(c);}
void drum_soft(Context& c,int key){auto& d=c.ui.drums;d.field_changed_at=c.now;if(d.confirm){if(key==0)d.confirm=false;else if(key==1)drum_push(c);return;}if(d.page==2&&c.ui.shift){
 drum_stop(c);
 if(key==0){d.muted[d.role]=!d.muted[d.role];c.notice(d.muted[d.role]?"Drum muted; omitted from Add":"Drum enabled");}
 else if(key==2){d.settings.locked[d.role]=!d.settings.locked[d.role];c.notice(d.settings.locked[d.role]?"Lane locked; new beats keep it":"Lane unlocked");}
 else if(d.settings.locked[d.role])c.notice("Unlock this lane to regenerate it");
 else if(d.stale||d.hits.empty())c.notice("Generate the full beat first");
 else {auto locks=d.settings.locked;d.settings=drum_lane_settings(d);bool made=generate(c,true);d.settings.locked=locks;if(made)c.notice("Selected drum lane regenerated");}
 return;}
 if(key==0){drum_stop(c);drum_back(d);}else if(key==1){if(d.page==1){auto_map(c);c.notice("Drum names mapped; check each role");}else generate(c,!d.stale&&!d.hits.empty());}else {drum_stop(c);if(d.page<3)drum_next(d);else drum_push(c);}}
void drum_browse_sound(Context& c){auto& d=c.ui.drums;if(!d.open||d.browsing||!valid(c)||!c.library){c.notice("Choose a drum kit before loading a sound");return;}drum_stop(c);int pad=drum_sound_destination(d,c.track());if(pad<0){c.notice("Map a pad first; no empty pads available");return;}d.sound_pad=uint8_t(pad);d.sound_role=d.role;d.previous_pad=c.track().last_pad;d.sound_load_requested=false;d.browsing=true;d.page=1;d.row=0;c.track().last_pad=uint8_t(pad);c.open_sample_select();c.notice(std::string("Choose ")+drums::role_name(d.sound_role)+" sound; Sample Select returns");}
void drum_sound_landed(Context& c,unsigned track,unsigned pad){auto& d=c.ui.drums;if(!drum_sound_matches(d,track,pad))return;d.pads[d.sound_role]=uint8_t(pad+1);d.sound_load_requested=false;d.field_changed_at=c.now;const bool returning=d.browsing&&c.ui.page==PageId::Samples&&c.ui.track==d.owner;d.browsing=false;c.project.tracks[track].last_pad=d.previous_pad;if(returning){c.stop_preview();if(c.library)c.library->preview("");c.open(PageId::Roll);}c.notice(std::string(drums::role_name(d.sound_role))+" sound loaded; beat settings kept");}
}
